INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'reunite', 'v.', '/ˌriːjuːˈnaɪt/', '(使)重聚;重新团聚', 'Mitch was reunited with his favourite professor after many years.', '多年之后,米奇与他最喜爱的教授重聚了。', 'Tuesdays with Morrie', 1, 0, 'senior', 'wordlist', 'elective4', 'U2', 'be reunited with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'weaken', 'v.', '/ˈwiːkən/', '(使)虚弱;削弱', 'Morrie was slowly weakened by a severe illness.', '莫里被一场重病一点点拖垮了身体。', 'Tuesdays with Morrie', 2, 0, 'senior', 'wordlist', 'elective4', 'U2', 'be weakened by', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'illness', 'n.', '/ˈɪlnəs/', '疾病;病', 'Despite his illness, Morrie stayed cheerful and full of hope.', '尽管身患疾病,莫里仍然乐观、满怀希望。', 'Tuesdays with Morrie', 3, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a severe illness', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'severe', 'adj.', '/sɪˈvɪə/', '严重的;严厉的', 'He was suffering from a severe illness that could not be cured.', '他患上了无法治愈的严重疾病。', 'Tuesdays with Morrie', 4, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a severe illness', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'professor', 'n.', '/prəˈfesə/', '教授', 'Morrie had been a much-loved college professor for many years.', '莫里多年来一直是一位深受爱戴的大学教授。', 'Tuesdays with Morrie', 5, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a college professor', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'journalist', 'n.', '/ˈdʒɜːnəlɪst/', '记者;新闻工作者', 'Before they met again, Mitch worked as a busy sports journalist.', '再次相见之前,米奇是一名忙碌的体育记者。', 'Tuesdays with Morrie', 6, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a sports journalist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pessimistic', 'adj.', '/ˌpesɪˈmɪstɪk/', '悲观的', 'The book is about dying, but it is not pessimistic at all.', '这本书写的是死亡,但一点也不悲观。', 'Tuesdays with Morrie', 7, 0, 'senior', 'wordlist', 'elective4', 'U2', 'feel pessimistic', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'anticipate', 'v.', '/ænˈtɪsɪpeɪt/', '预期;预料', 'As Morrie anticipated his own death, he saw the world through new eyes.', '当莫里预料到自己的死亡时,他用全新的眼光看世界。', 'Tuesdays with Morrie', 8, 0, 'senior', 'wordlist', 'elective4', 'U2', 'anticipate one''s own death', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'possession', 'n.', '/pəˈzeʃn/', '财产;财物;拥有', 'Morrie warned us not to value material possessions too much.', '莫里告诫我们不要太看重物质财产。', 'Tuesdays with Morrie', 9, 0, 'senior', 'wordlist', 'elective4', 'U2', 'material possessions', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'abnormal', 'adj.', '/æbˈnɔːml/', '不正常的;反常的', 'Looking different from others does not make a person abnormal.', '与别人长得不同并不会让一个人变得不正常。', 'Tuesdays with Morrie', 10, 0, 'senior', 'wordlist', 'elective4', 'U2', 'make sb abnormal', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'widespread', 'adj.', '/ˈwaɪdspred/', '广泛的;普遍的', 'The book has gained widespread recognition around the world.', '这本书已在世界范围内获得广泛认可。', 'Tuesdays with Morrie', 11, 0, 'senior', 'wordlist', 'elective4', 'U2', 'widespread recognition', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'recognition', 'n.', '/ˌrekəɡˈnɪʃn/', '承认;认可;赏识', 'Despite its recognition, some readers doubted the book at first.', '尽管这本书受到认可,有些读者起初却心存怀疑。', 'Tuesdays with Morrie', 12, 0, 'senior', 'wordlist', 'elective4', 'U2', 'gain recognition', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'phrase', 'n.', '/freɪz/', '短语;警句;习语', 'Each lesson is summed up in a short, memorable phrase.', '每条道理都被浓缩成一句简短而难忘的警句。', 'Tuesdays with Morrie', 13, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a short phrase', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cooperate', 'v.', '/kəʊˈɒpəreɪt/', '合作;协作', 'It is easier to succeed if you cooperate with someone else.', '如果你与他人合作,就更容易成功。', 'Tuesdays with Morrie', 14, 0, 'senior', 'wordlist', 'elective4', 'U2', 'cooperate with sb', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fee', 'n.', '/fiː/', '费用;酬金', 'University fees were no barrier to the determined grandmother.', '大学学费对这位有决心的老奶奶来说不是障碍。', 'Tuesdays with Morrie', 15, 0, 'senior', 'wordlist', 'elective4', 'U2', 'university fees', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pure', 'adj.', '/pjʊə/', '纯净的;纯粹的', 'In the play, the Happiness of Pure Air is almost invisible.', '在剧中,纯净空气之幸福几乎是看不见的。', 'Tuesdays with Morrie', 16, 0, 'senior', 'wordlist', 'elective4', 'U2', 'pure air', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'luxury', 'n.', '/ˈlʌkʃəri/', '奢华;奢侈品', 'Happiness is not found in luxury, but in simple, everyday things.', '幸福不在于奢华,而在于简单的日常小事。', 'Tuesdays with Morrie', 17, 0, 'senior', 'wordlist', 'elective4', 'U2', 'live in luxury', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'despair', 'n.', '/dɪˈspeə/', '绝望', 'Even when he was very ill, Morrie was never filled with despair.', '即使病得很重,莫里也从未陷入绝望。', 'Tuesdays with Morrie', 18, 0, 'senior', 'wordlist', 'elective4', 'U2', 'be filled with despair', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'absurd', 'adj.', '/əbˈsɜːd/', '荒唐的;可笑的', 'At first the old man''s calm words sounded a little absurd to me.', '起初,这位老人平静的话在我听来有点荒唐。', 'Tuesdays with Morrie', 19, 0, 'senior', 'wordlist', 'elective4', 'U2', 'sound absurd', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cram', 'v.', '/kræm/', '塞满;挤满', 'Morrie believed that an ordinary home is crammed with small happinesses.', '莫里相信,一个普通的家里挤满了细小的幸福。', 'Tuesdays with Morrie', 20, 0, 'senior', 'wordlist', 'elective4', 'U2', 'be crammed with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'transparent', 'adj.', '/trænsˈpærənt/', '透明的', 'The Happiness of Pure Air was so light that it seemed transparent.', '纯净空气之幸福如此轻盈,仿佛是透明的。', 'Tuesdays with Morrie', 21, 0, 'senior', 'wordlist', 'elective4', 'U2', 'almost transparent', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'inspirational', 'adj.', '/ˌɪnspəˈreɪʃənl/', '鼓舞人心的;给人启发的', 'Morrie''s bravery near the end of his life was truly inspirational.', '莫里生命尽头的勇敢确实鼓舞人心。', 'Tuesdays with Morrie', 22, 0, 'senior', 'wordlist', 'elective4', 'U2', 'an inspirational story', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bravery', 'n.', '/ˈbreɪvəri/', '勇敢;勇气', 'His quiet bravery moved everyone who read the book.', '他那份平静的勇敢打动了每一个读这本书的人。', 'Tuesdays with Morrie', 23, 0, 'senior', 'wordlist', 'elective4', 'U2', 'show bravery', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'reflection', 'n.', '/rɪˈflekʃn/', '沉思;反思;映像', 'Morrie''s reflections on love and friendship made me think deeply.', '莫里对爱与友谊的沉思让我陷入深思。', 'Tuesdays with Morrie', 24, 0, 'senior', 'wordlist', 'elective4', 'U2', 'reflections on love', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'perish', 'v.', '/ˈperɪʃ/', '死亡;消亡;毁灭', 'Morrie''s favourite poet wrote, "Love each other or perish."', '莫里最爱的诗人写道:“彼此相爱,否则消亡。”', 'Tuesdays with Morrie', 25, 0, 'senior', 'wordlist', 'elective4', 'U2', 'love or perish', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'distract', 'v.', '/dɪˈstrækt/', '使分心;转移注意力', 'While we are living, we are easily distracted by small worries.', '活着的时候,我们很容易被琐碎的烦恼分散注意力。', 'Tuesdays with Morrie', 26, 0, 'senior', 'wordlist', 'elective4', 'U2', 'be distracted by', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'material', 'adj.', '/məˈtɪəriəl/', '物质的;实物的', 'He warned young people against chasing only material things.', '他告诫年轻人不要只追求物质的东西。', 'Tuesdays with Morrie', 27, 0, 'senior', 'wordlist', 'elective4', 'U2', 'material possessions', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'impression', 'n.', '/ɪmˈpreʃn/', '印象;感想', 'My first impression of the book turned out to be quite wrong.', '我对这本书的最初印象后来证明大错特错。', 'Tuesdays with Morrie', 28, 0, 'senior', 'wordlist', 'elective4', 'U2', 'first impression', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'determine', 'v.', '/dɪˈtɜːmɪn/', '决定;确定', 'You should not let any society determine your values for you.', '你不该让任何社会替你决定自己的价值观。', 'Tuesdays with Morrie', 29, 0, 'senior', 'wordlist', 'elective4', 'U2', 'determine sth for sb', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'value', 'v./n.', '/ˈvæljuː/', '珍视;重视;价值;价值观', 'Morrie taught us to value our own lives a little more.', '莫里教会我们更珍视自己的生命。', 'Tuesdays with Morrie', 30, 0, 'senior', 'wordlist', 'elective4', 'U2', 'establish one''s own values', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'society', 'n.', '/səˈsaɪəti/', '社会', 'He said no society should choose what really matters for you.', '他说,没有哪个社会该替你选择什么才是真正重要的。', 'Tuesdays with Morrie', 31, 0, 'senior', 'wordlist', 'elective4', 'U2', 'let society decide', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'insight', 'n.', '/ˈɪnsaɪt/', '洞察力;深刻理解', 'After finishing it, I felt I had a deeper insight into life.', '读完之后,我觉得自己对人生有了更深的洞察。', 'Tuesdays with Morrie', 32, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a deeper insight', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'recommend', 'v.', '/ˌrekəˈmend/', '推荐;建议', 'Although it isn''t my favourite book, I would still recommend it.', '虽然它不是我最喜欢的书,我仍然会推荐它。', 'Tuesdays with Morrie', 33, 0, 'senior', 'wordlist', 'elective4', 'U2', 'recommend a book', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'emotional', 'adj.', '/ɪˈməʊʃənl/', '情感的;动情的', 'At first it seemed like a set of over-emotional thoughts.', '起初它看起来像是一堆过于煽情的想法。', 'Tuesdays with Morrie', 34, 0, 'senior', 'wordlist', 'elective4', 'U2', 'over-emotional thoughts', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'influence', 'v./n.', '/ˈɪnfluəns/', '影响', 'The book made me see how much I am influenced by popular culture.', '这本书让我看清自己受流行文化影响有多深。', 'Tuesdays with Morrie', 35, 0, 'senior', 'wordlist', 'elective4', 'U2', 'be influenced by', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'communication', 'n.', '/kəˌmjuːnɪˈkeɪʃn/', '交流;沟通', 'Real values are built on love and open communication.', '真正的价值观建立在爱与坦诚的沟通之上。', 'Tuesdays with Morrie', 36, 0, 'senior', 'wordlist', 'elective4', 'U2', 'open communication', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'friendship', 'n.', '/ˈfrendʃɪp/', '友谊;友情', 'His gentle words about friendship touched me the most.', '他关于友谊的温柔话语最打动我。', 'Tuesdays with Morrie', 37, 0, 'senior', 'wordlist', 'elective4', 'U2', 'reflections on friendship', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'observe', 'v.', '/əbˈzɜːv/', '观察;注意到;遵守', 'From his window, Morrie observed every change of season.', '莫里从窗口观察着每一次季节的变化。', 'Tuesdays with Morrie', 38, 0, 'senior', 'wordlist', 'elective4', 'U2', 'observe everything', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'appreciate', 'v.', '/əˈpriːʃieɪt/', '珍惜;欣赏;感激', 'The book encourages us to appreciate what we already have.', '这本书鼓励我们珍惜已经拥有的东西。', 'Tuesdays with Morrie', 39, 0, 'senior', 'wordlist', 'elective4', 'U2', 'appreciate what we have', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'wisdom', 'n.', '/ˈwɪzdəm/', '智慧;明智', 'Storytelling has long been a way to pass on wisdom.', '讲故事长久以来都是传递智慧的一种方式。', 'Tuesdays with Morrie', 40, 0, 'senior', 'wordlist', 'elective4', 'U2', 'pass on wisdom', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'journey', 'n.', '/ˈdʒɜːni/', '旅程;历程', 'A wise mentor walks with us on the journey of life.', '一位智慧的引路人会陪我们走过人生的旅程。', 'Tuesdays with Morrie', 41, 0, 'senior', 'wordlist', 'elective4', 'U2', 'the journey of life', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'moral', 'n.', '/ˈmɒrəl/', '寓意;道德准则', 'Each fable ends with a short moral that teaches a lesson.', '每则寓言都以一句简短的寓意作结,告诉人们一个道理。', 'Tuesdays with Morrie', 42, 0, 'senior', 'wordlist', 'elective4', 'U2', 'the moral of a story', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fable', 'n.', '/ˈfeɪbl/', '寓言', 'Aesop''s Fables teach important truths through animal stories.', '《伊索寓言》通过动物故事讲述重要的道理。', 'Tuesdays with Morrie', 43, 0, 'senior', 'wordlist', 'elective4', 'U2', 'Aesop''s Fables', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'credit', 'v./n.', '/ˈkredɪt/', '把……归功于;赞扬;信任', 'History credits these famous fables to a Greek storyteller.', '历史把这些著名的寓言归功于一位希腊讲故事的人。', 'Tuesdays with Morrie', 44, 0, 'senior', 'wordlist', 'elective4', 'U2', 'credit sth to sb', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'trait', 'n.', '/treɪt/', '特点;特征', 'Aesop used animals to reflect common human traits.', '伊索用动物来映照人类共有的特点。', 'Tuesdays with Morrie', 45, 0, 'senior', 'wordlist', 'elective4', 'U2', 'human traits', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'summarise', 'v.', '/ˈsʌməraɪz/', '概括;总结', 'He summarised each life lesson in just one simple sentence.', '他用简单的一句话概括了每一条人生道理。', 'Tuesdays with Morrie', 46, 0, 'senior', 'wordlist', 'elective4', 'U2', 'summarise a lesson', '美式拼 summarize;美音 /ˈsʌməraɪz/', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'barrier', 'n.', '/ˈbæriə/', '障碍;阻碍;屏障', 'Age was no barrier to the grandmother who returned to study.', '对重返校园的老奶奶来说,年龄不是障碍。', 'Tuesdays with Morrie', 47, 0, 'senior', 'wordlist', 'elective4', 'U2', 'no barrier to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'graduate', 'v.', '/ˈɡrædʒueɪt/', '毕业', 'After years of effort, she finally graduated from university.', '经过多年努力,她终于从大学毕业了。', 'Tuesdays with Morrie', 48, 0, 'senior', 'wordlist', 'elective4', 'U2', 'graduate from university', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u2.01', '①一般时态被动(is/was/will be done,看时间标志判断)', 'A2', 12, '外研社版选择性必修第四册 U2 — 主语是动作的承受者时用被动:现在 is/are done、过去 was/were done、将来 will be done;由句中时间标志(today/nowadays、last week/ago/in 1997、tomorrow/next year 等)决定时态;主动形式因主语不发出动作而排除。', 1, 'elective4', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u2.02', '②完成/进行时态被动(has been done · is being done · had been done)', 'A2', 12, '外研社版选择性必修第四册 U2 — 现在完成被动 has/have been done(already/so far/since);过去完成被动 had been done(by the time…、by 1997);现在进行被动 is/are being done(right now/look!);过去进行被动 was/were being done(while…、when… came)。靠标志选一种。', 2, 'elective4', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u2.03', '③非谓语被动 + 情态被动 + 主动/被动选择(to be done · being done · must be done)', 'A2', 12, '外研社版选择性必修第四册 U2 — need/want/ask + to be done;介词(despite/after/without/by)+ being done;情态 must/should/can/will + be done;再由主语是施动者还是承受者,在主动与被动之间作选择。', 3, 'elective4', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'Nowadays, Morrie''s lessons ____ by readers around the world.', 'are shared', 'were shared', 'will be shared', 'share', 'A', '时间标志 Nowadays 指现在、主语 lessons 是被分享的对象 → 一般现在被动 are shared。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'The very first review of the book ____ by a journalist back in 1997.', 'is written', 'was written', 'will be written', 'writes', 'B', 'back in 1997 指过去、review 被写 → 一般过去被动 was written。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'A new film about the book ____ next year.', 'was made', 'is made', 'will be made', 'makes', 'C', 'next year 指将来、film 被拍 → 一般将来被动 will be made。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'Today this moving novel ____ in many school libraries.', 'was found', 'will be found', 'finds', 'is found', 'D', 'Today 指现在、novel 被找到/陈列 → 一般现在被动 is found。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'Mitch ____ deeply by his old teacher''s courage last winter.', 'was moved', 'is moved', 'will be moved', 'moves', 'A', 'last winter 指过去、Mitch 被打动 → 一般过去被动 was moved。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'These study notes ____ to the new students tomorrow.', 'were given', 'will be given', 'are given', 'give', 'B', 'tomorrow 指将来、notes 被发放 → 一般将来被动 will be given。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'Every week, fresh flowers ____ to Morrie''s room by his students.', 'were brought', 'will be brought', 'are brought', 'bring', 'C', 'Every week 表示现在的习惯、flowers 被送来 → 一般现在被动 are brought。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'The old photograph ____ on the wall years ago.', 'is hung', 'will be hung', 'hangs', 'was hung', 'D', 'years ago 指过去、photograph 被挂 → 一般过去被动 was hung。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'The professor''s wisdom ____ down to future readers one day.', 'will be passed', 'was passed', 'is passed', 'passes', 'A', 'one day 指将来、wisdom 被传递 → 一般将来被动 will be passed。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'At present, the book ____ into more than thirty languages.', 'was translated', 'is translated', 'will be translated', 'translates', 'B', 'At present 指现在、book 被翻译 → 一般现在被动 is translated。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'His final lecture ____ by the whole class yesterday.', 'is recorded', 'will be recorded', 'was recorded', 'records', 'C', 'yesterday 指过去、lecture 被录下 → 一般过去被动 was recorded。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'A special edition of the novel ____ this coming spring.', 'was printed', 'is printed', 'prints', 'will be printed', 'D', 'this coming spring 指将来、edition 被印刷 → 一般将来被动 will be printed。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'These days, a few kind words ____ more than expensive gifts.', 'are valued', 'were valued', 'will be valued', 'value', 'A', 'These days 指现在、words 被珍视 → 一般现在被动 are valued。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'The interview with Morrie ____ on the radio last night.', 'is broadcast', 'was broadcast', 'will be broadcast', 'broadcasts', 'B', 'last night 指过去、interview 被播出 → 一般过去被动 was broadcast。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'Many copies of the book ____ to the charity sale next week.', 'were donated', 'are donated', 'will be donated', 'donate', 'C', 'next week 指将来、copies 被捐赠 → 一般将来被动 will be donated。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'Usually the book club''s choice ____ by all the members together.', 'was made', 'will be made', 'makes', 'is made', 'D', 'Usually 表示现在的习惯、choice 被决定 → 一般现在被动 is made。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'Morrie ____ to hospital two years ago when his illness grew worse.', 'was taken', 'is taken', 'will be taken', 'takes', 'A', 'two years ago 指过去、Morrie 被送 → 一般过去被动 was taken。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'The new reading list ____ to parents this coming weekend.', 'was sent', 'will be sent', 'is sent', 'sends', 'B', 'this coming weekend 指将来、list 被发送 → 一般将来被动 will be sent。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'Generally, his gentle advice ____ by people of all ages.', 'was followed', 'will be followed', 'is followed', 'follows', 'C', 'Generally 表示一般情况(现在)、advice 被遵循 → 一般现在被动 is followed。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.01'), 'That famous course ____ by Professor Schwartz for many years before he retired.', 'is taught', 'will be taught', 'teaches', 'was taught', 'D', 'before he retired 指过去、course 被讲授 → 一般过去被动 was taught。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'So far, the book ____ into more than forty languages.', 'has been translated', 'was translated', 'is being translated', 'had been translated', 'A', 'So far 与现在相连 → 现在完成被动 has been translated。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'Right now, a new cover ____ for the next edition.', 'has been designed', 'is being designed', 'was designed', 'had been designed', 'B', 'Right now 表示此刻正在 → 现在进行被动 is being designed。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'By the time Mitch came in, the lesson ____.', 'has been finished', 'was being finished', 'had been finished', 'is finished', 'C', 'By the time + 过去动作,之前已完成 → 过去完成被动 had been finished。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'When the nurse entered, Morrie ____ gently by his wife.', 'has been helped', 'had been helped', 'is being helped', 'was being helped', 'D', '过去某动作发生时正在进行 → 过去进行被动 was being helped。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'Morrie''s story ____ on the evening news already.', 'has been shown', 'is being shown', 'was being shown', 'had been shown', 'A', 'already 与现在相连 → 现在完成被动 has been shown。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'Look! The old lecture hall ____ for the memorial.', 'has been decorated', 'is being decorated', 'was decorated', 'had been decorated', 'B', 'Look! 表示此刻正在 → 现在进行被动 is being decorated。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'Mitch realised that the manuscript ____ before the deadline.', 'has been completed', 'is being completed', 'had been completed', 'was being completed', 'C', '过去 realised 之前更早完成 → 过去完成被动 had been completed。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'Up to now, thousands of warm letters ____ to the author.', 'are being sent', 'had been sent', 'were being sent', 'have been sent', 'D', 'Up to now 与现在相连 → 现在完成被动 have been sent。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'While the interview ____, the telephone suddenly rang.', 'was being recorded', 'has been recorded', 'had been recorded', 'is being recorded', 'A', 'While + 过去正在进行 → 过去进行被动 was being recorded。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'At the moment, a documentary about Morrie ____.', 'has been filmed', 'is being filmed', 'was being filmed', 'had been filmed', 'B', 'At the moment 表示此刻正在 → 现在进行被动 is being filmed。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'The novel ____ widely since it first appeared.', 'is being read', 'was being read', 'has been read', 'had been read', 'C', 'since + 过去到现在 → 现在完成被动 has been read。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'By 1997, the book ____ by millions of readers.', 'has been bought', 'is being bought', 'was being bought', 'had been bought', 'D', 'By 1997(过去时间点之前)→ 过去完成被动 had been bought。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'Currently, his ideas about life ____ in many classrooms.', 'are being discussed', 'have been discussed', 'had been discussed', 'were being discussed', 'A', 'Currently 表示此刻正在 → 现在进行被动 are being discussed。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'When Mitch knocked at the door, Morrie ____ to a softer chair.', 'has been moved', 'was being moved', 'had been moved', 'is being moved', 'B', '过去某动作发生时正被搬动 → 过去进行被动 was being moved。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'Recently, the play of the story ____ in several theatres.', 'is being performed', 'had been performed', 'has been performed', 'was being performed', 'C', 'Recently 与现在相连 → 现在完成被动 has been performed。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'The old man told us his garden ____ long before he fell ill.', 'has been planted', 'is being planted', 'was being planted', 'had been planted', 'D', '比过去 fell ill 更早完成 → 过去完成被动 had been planted。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'Right now, the final chapter ____ aloud to the whole class.', 'is being read', 'has been read', 'was read', 'had been read', 'A', 'Right now 表示此刻正在 → 现在进行被动 is being read。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'So far, the message of love ____ by many young readers.', 'is being understood', 'has been understood', 'had been understood', 'was being understood', 'B', 'So far 与现在相连 → 现在完成被动 has been understood。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'At that moment yesterday, the meeting room ____ for the visitors.', 'has been cleaned', 'had been cleaned', 'was being cleaned', 'is being cleaned', 'C', 'At that moment yesterday(过去某刻正在)→ 过去进行被动 was being cleaned。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.02'), 'Before the bell rang, all the homework ____ in.', 'has been handed', 'is being handed', 'was being handed', 'had been handed', 'D', '比过去 rang 更早完成 → 过去完成被动 had been handed。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Such important life lessons need ____ on to the young.', 'to be passed', 'to pass', 'passing', 'passed', 'A', 'need + 不定式被动,lessons 是被传递的对象 → to be passed。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Despite ____ by a serious illness, Morrie stayed cheerful.', 'weakening', 'being weakened', 'to weaken', 'weaken', 'B', '介词 Despite 后接动名词、Morrie 被削弱 → being weakened。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'A box of tissues will ____ to get through this moving book.', 'need', 'being needed', 'be needed', 'needs', 'C', 'will + 情态/将来被动,tissues 被需要 → be needed。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Every Tuesday, Mitch ____ his old professor at his house.', 'was visited', 'being visited', 'to be visited', 'visited', 'D', '主语 Mitch 是探望的发出者 → 用主动 visited。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'The kind old professor ____ by Mitch every Tuesday.', 'was visited', 'visited', 'visiting', 'to visit', 'A', '主语 professor 是被探望的对象、有 by Mitch → 用被动 was visited。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'These values are too personal ____ by anyone else.', 'to decide', 'to be decided', 'deciding', 'decided', 'B', 'too…to + 被动不定式,values 被决定 → to be decided。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'After ____ widely by critics, the novel became a bestseller.', 'reviewing', 'to review', 'being reviewed', 'reviewed', 'C', '介词 After 后接动名词、novel 被评论 → being reviewed。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Your own values must ____ by yourself, not by society.', 'choose', 'being chosen', 'chooses', 'be chosen', 'D', '情态 must + 被动,values 被选择 → be chosen。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'From his window, Morrie ____ everything as though through new eyes.', 'observed', 'was observed', 'being observed', 'to be observed', 'A', '主语 Morrie 是观察的发出者 → 用主动 observed。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Mitch wanted his teacher''s wisdom ____ down for others.', 'to record', 'to be recorded', 'recording', 'recorded', 'B', 'want + 宾语 + 不定式被动,wisdom 被记录 → to be recorded。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Without ____ properly, the book''s message can easily be missed.', 'explaining', 'to explain', 'being explained', 'explained', 'C', '介词 Without 后接动名词、message 被解释 → being explained。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Such a moving story should ____ by everyone at least once.', 'read', 'being read', 'to be read', 'be read', 'D', '情态 should + 被动(by everyone),story 被读 → be read。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'The whole book ____ in less than a year by a grateful student.', 'was written', 'wrote', 'writing', 'to write', 'A', '主语 book 是被写的对象、有 by…→ 用被动 was written。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Mitch ____ the story so that others could learn from Morrie.', 'was written', 'wrote', 'being written', 'to be written', 'B', '主语 Mitch 是写作的发出者 → 用主动 wrote。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Important truths can ____ even in the shortest of stories.', 'find', 'being found', 'be found', 'finds', 'C', '情态 can + 被动,truths 被发现 → be found。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Near the end, the dying man asked ____ closer to the window.', 'to move', 'moving', 'moved', 'to be moved', 'D', 'ask + 不定式被动,他被移动 → to be moved。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'By ____ by a wise teacher, we slowly learn how to live.', 'being guided', 'guiding', 'to guide', 'guided', 'A', '介词 By 后接动名词、we 被引导 → being guided。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Such quiet bravery may never ____ by those who read the book.', 'forget', 'be forgotten', 'being forgotten', 'forgets', 'B', '情态 may + 被动,bravery 被遗忘 → be forgotten。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Old friendships deserve ____ alive with a few warm words.', 'to keep', 'keeping', 'to be kept', 'kept', 'C', 'deserve + 不定式被动,friendships 被保持 → to be kept。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U2' AND code='fe4u2.03'), 'Great respect ____ to Morrie by all of his former students.', 'gave', 'giving', 'to give', 'was given', 'D', '主语 respect 是被给予的对象、有 by…→ 用被动 was given。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Book About Life, Not Death', 'Tuesdays with Morrie is one of the most loved books about life ever written. Its author, Mitch Albom, was a busy sports journalist who felt that something was missing from his days. Everything changed when he was reunited with his favourite college professor, Morrie Schwartz. On learning that Morrie was being weakened by a severe illness, Mitch began visiting him every Tuesday. During these weekly talks, many lessons on the meaning of life were shared between the two friends. Although the book is about dying, it is not pessimistic at all. Instead, it is filled with joy and hope. Morrie''s bravery near the end of his life has been described as inspirational, and it has encouraged countless readers to value their own lives more. Far from being a sad story about death, it gently reminds us that once we learn how to die, we finally learn how to live.', '说明·全书介绍', 149, '[{"q":"What was Mitch Albom''s job before he met Morrie again?","answer":"A","options":["A sports journalist.","A college professor.","A hospital doctor.","A film director."],"explanation":"原文 ''a busy sports journalist'' 的转述。"},{"q":"Why did Mitch start visiting Morrie every Tuesday?","answer":"B","options":["Because Morrie had offered him money.","Because Morrie had become seriously ill.","Because they had become neighbours.","Because Mitch had lost his job."],"explanation":"原文 ''was being weakened by a severe illness'' 的转述。"},{"q":"What does the writer say the book is really about?","answer":"A","options":["Living well, not just dying.","Becoming rich and famous.","Winning sports matches.","Travelling around the world."],"explanation":"末句 ''once we learn how to die, we finally learn how to live'' 的转述。"}]'::jsonb, '[{"word":"journalist","cn":"记者"},{"word":"reunite","cn":"(使)重聚"},{"word":"inspirational","cn":"鼓舞人心的"}]'::jsonb, 2, 'elective4', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Who Was Morrie Schwartz?', 'Morrie Schwartz was loved by his students long before he became known around the world. For many years he had taught at a university, where his lessons were remembered not only for their clever ideas but also for their warmth. When a severe illness slowly took away his strength, Morrie was not filled with despair. He chose instead to share what he had learned about love, work and friendship. From his window, each change of season was observed by him as though through new eyes, and ordinary things seemed more beautiful than ever before. His former student Mitch wrote down their conversations so that the old teacher''s wisdom could be passed on. In this way, the quiet courage of one dying professor has been turned into a message of hope. Today that message is read by millions of people in many different countries.', '人物·莫里其人', 143, '[{"q":"How were Morrie''s university lessons remembered?","answer":"B","options":["For being extremely strict.","For both their ideas and their warmth.","For being very difficult.","For being rather boring."],"explanation":"原文 ''remembered not only for their clever ideas but also for their warmth'' 的转述。"},{"q":"How did Morrie react to his illness?","answer":"C","options":["He stopped speaking to everyone.","He hid himself away in despair.","He shared what he had learned instead of giving up.","He blamed his former students."],"explanation":"原文 ''chose instead to share what he had learned'' 的转述。"},{"q":"Why did Mitch write down their talks?","answer":"D","options":["So that he could become a sports star.","So that he could sell the old house.","So that he could forget his teacher.","So that Morrie''s wisdom could reach others."],"explanation":"原文 ''so that the old teacher''s wisdom could be passed on'' 的转述。"}]'::jsonb, '[{"word":"despair","cn":"绝望"},{"word":"observe","cn":"观察"},{"word":"wisdom","cn":"智慧"}]'::jsonb, 2, 'elective4', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Big Things in Life', 'One of the strongest messages in Tuesdays with Morrie is about the so-called ''big things'' in life. According to Morrie, how we think and what we value should be chosen by ourselves, and never be decided for us by any society. While we are living, we are easily distracted by smaller matters, such as gathering material possessions. Yet money, Morrie warns, will not always make people happy, and looking different from others does not make a person abnormal. Readers are encouraged to find out for themselves what truly matters and to build their own values around love and honest communication. Many who finish the book say they feel as if they have been woken from a long sleep. Their eyes are opened to the world, and small daily worries are suddenly seen as far less important than simple kindness.', '议论·人生大事', 139, '[{"q":"According to Morrie, who should decide your values?","answer":"A","options":["You should decide them yourself.","Society should decide them for you.","Your boss should decide them.","No one needs any values."],"explanation":"原文 ''should be chosen by ourselves'' 的转述。"},{"q":"What does Morrie say about money?","answer":"B","options":["It is the most important thing of all.","It does not always bring happiness.","It should always be hidden away.","It makes a person abnormal."],"explanation":"原文 ''money… will not always make people happy'' 的转述。"},{"q":"How do many readers feel after finishing the book?","answer":"C","options":["Angry and deeply disappointed.","Bored and rather sleepy.","Suddenly more awake and aware of life.","Sorry that they ever read it."],"explanation":"原文 ''as if they have been woken from a long sleep'' 的转述。"}]'::jsonb, '[{"word":"determine","cn":"决定"},{"word":"possession","cn":"财产"},{"word":"abnormal","cn":"不正常的"}]'::jsonb, 2, 'elective4', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Wisdom in Old Stories', 'Long before printed books existed, wisdom was passed on through storytelling. One of the earliest collections of such stories is Aesop''s Fables, which history credits to a Greek storyteller named Aesop. It is believed that he lived in ancient Greece more than two thousand years ago. Most of the characters in his tales are animals, whose qualities were cleverly used by Aesop to reflect human nature. At the end of each fable, a short lesson, known as a moral, is given in a single memorable phrase. Because these morals are simple and true, they have never been forgotten. Today, Aesop''s Fables are still enjoyed by both children and adults all over the world. The stories remind us that important truths can be found even in the shortest of tales, and that lessons about life are often best remembered when they are wrapped inside a good story.', '说明·伊索寓言', 146, '[{"q":"How was wisdom shared before printed books existed?","answer":"D","options":["Through television programmes.","Through daily newspapers.","Through the internet.","Through telling stories."],"explanation":"原文 ''wisdom was passed on through storytelling'' 的转述。"},{"q":"Why did Aesop use animals in his stories?","answer":"A","options":["To reflect human nature.","To teach modern science.","To sell far more books.","To frighten young children."],"explanation":"原文 ''used by Aesop to reflect human nature'' 的转述。"},{"q":"What is a ''moral'' in one of Aesop''s fables?","answer":"B","options":["The full name of the writer.","A short lesson at the end of the story.","A long introduction to the tale.","A list of all the animals."],"explanation":"原文 ''a short lesson, known as a moral'' 的转述。"}]'::jsonb, '[{"word":"fable","cn":"寓言"},{"word":"credit","cn":"把…归功于"},{"word":"moral","cn":"寓意"}]'::jsonb, 2, 'elective4', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Searching for the Blue Bird', 'The Blue Bird is a famous play in which two children, Tyltyl and Mytyl, are sent by a fairy to search for the Blue Bird of Happiness. Their long adventure takes them through many magical places, yet the bird they are looking for is never quite caught. Only when the tired children return home is the truth finally understood: the Blue Bird had been there all the time. Happiness, the play suggests, is not to be found in luxury or wealth, but in simple things such as family life and acts of kindness. Near the end, the bird is given to a sick neighbour''s daughter, and the little girl is suddenly cured. Then, in a surprising moment, the bird escapes and flies away, and the audience is asked to help find it again. Through this gentle ending, we are reminded that happiness must always be searched for and shared.', '戏剧·青鸟与幸福', 149, '[{"q":"What are the two children sent to look for?","answer":"C","options":["A box full of gold.","A lost family dog.","A magical bird that stands for happiness.","An old magic book."],"explanation":"原文 ''search for the Blue Bird of Happiness'' 的转述。"},{"q":"Where does the play say happiness is found?","answer":"D","options":["In great wealth and luxury.","In faraway magical lands.","In winning a competition.","In simple things like family and kindness."],"explanation":"原文 ''in simple things such as family life and acts of kindness'' 的转述。"},{"q":"What happens to the bird at the very end?","answer":"A","options":["It flies away and must be found again.","It is sold at a busy market.","It turns into a piece of gold.","It is locked in a cage forever."],"explanation":"原文 ''the bird escapes and flies away… asked to help find it again'' 的转述。"}]'::jsonb, '[{"word":"luxury","cn":"奢华"},{"word":"pure","cn":"纯净的"},{"word":"despair","cn":"绝望"}]'::jsonb, 2, 'elective4', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Never Too Late to Learn', 'Age, as one remarkable story shows, need not be a barrier to learning. Many years ago, a woman named Janet had to leave university before finishing her degree, because her family came first. The dream of graduating, however, was never completely given up. When her children had grown, she returned to study, even though at first she felt nervous among classmates who were far younger than she was. Her courage was soon rewarded. After several years of hard work, she finally graduated, and her happy story was reported in the local news. Today, more and more older students are being welcomed by universities, and in some countries no upper age limit is set at all. Janet''s advice to others is simple: it is never too late to start again. A goal that is truly worth reaching, she believes, should be followed at any age.', '记叙·八旬毕业生', 144, '[{"q":"Why did Janet first leave university?","answer":"B","options":["She strongly disliked studying.","Her family had to come first.","She had no money for books.","She suddenly moved abroad."],"explanation":"原文 ''because her family came first'' 的转述。"},{"q":"How did Janet feel when she returned to study?","answer":"C","options":["Proud and completely relaxed.","Angry at all her teachers.","Nervous among much younger classmates.","Bored by the easy lessons."],"explanation":"原文 ''felt nervous among classmates who were far younger'' 的转述。"},{"q":"What is Janet''s advice to other people?","answer":"D","options":["Only the young should ever study.","Give up quickly if learning is hard.","Avoid universities completely.","You can always begin again, whatever your age."],"explanation":"原文 ''it is never too late to start again'' 的转述。"}]'::jsonb, '[{"word":"barrier","cn":"障碍"},{"word":"graduate","cn":"毕业"},{"word":"fee","cn":"费用"}]'::jsonb, 2, 'elective4', 'U2', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U2', 'A Letter to a Mentor', 'Dear Mr Lin, I am writing to thank you for everything you have (1)____ me over these three years. When I first joined your class, I was shy and often felt that something was (2)____ from my life. You taught me that the (3)____ things — how we think and what we value — must be chosen by ourselves. Like Morrie in my favourite (4)____, you never seemed (5)____, even on the most difficult days. Instead, you were always full of hope and quiet (6)____. You once said that money would not always make us (7)____, and that we should (8)____ what we already have. Those gentle words have stayed with me ever (9)____. Whenever I feel lost, your advice is still (10)____ safely in my heart. Thank you for being both my teacher and my friend.', 137, 2, '[{"q":"1","answer":"A","options":["taught","sold","thrown","bought"],"explanation":"thank you for everything you have taught me 教给我。"},{"q":"2","answer":"B","options":["shining","missing","sleeping","cooking"],"explanation":"something was missing 缺了什么。"},{"q":"3","answer":"C","options":["cheap","loud","big","empty"],"explanation":"the big things 人生大事。"},{"q":"4","answer":"D","options":["garden","market","machine","book"],"explanation":"my favourite book 我最爱的书。"},{"q":"5","answer":"A","options":["pessimistic","hungry","sleepy","late"],"explanation":"never seemed pessimistic 从不显得悲观。"},{"q":"6","answer":"B","options":["noise","joy","dust","traffic"],"explanation":"full of hope and joy 满怀喜悦。"},{"q":"7","answer":"C","options":["angry","absent","happy","quiet"],"explanation":"make us happy 让我们快乐。"},{"q":"8","answer":"D","options":["waste","sell","forget","appreciate"],"explanation":"appreciate what we have 珍惜所拥有的。"},{"q":"9","answer":"A","options":["since","ago","then","once"],"explanation":"ever since 自那以后一直。"},{"q":"10","answer":"B","options":["lost","kept","thrown","sold"],"explanation":"kept safely in my heart 珍藏在心里。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U2', 'Morrie at the Window', 'As his illness grew worse, Morrie spent many quiet hours by his (1)____. From there, each change of (2)____ was watched by him as though through new eyes. The trees, the sky and the falling leaves all seemed more (3)____ than ever before. He knew that this autumn might be his (4)____, yet he was not filled with (5)____. Instead, he chose to (6)____ every small thing around him. He told Mitch that once you learn how to (7)____, you also learn how to truly live. Ordinary moments, he said, should never be (8)____ for granted. People who are always busy often (9)____ such beauty completely. Morrie''s calm words have (10)____ many readers to slow down and notice the world.', 120, 2, '[{"q":"1","answer":"C","options":["wallet","ticket","window","engine"],"explanation":"by his window 在窗边。"},{"q":"2","answer":"D","options":["price","noise","machine","season"],"explanation":"change of season 季节变化。"},{"q":"3","answer":"A","options":["beautiful","boring","ugly","cheap"],"explanation":"more beautiful 更美。"},{"q":"4","answer":"B","options":["first","last","cheap","loud"],"explanation":"his last autumn 他最后的秋天。"},{"q":"5","answer":"C","options":["laughter","money","despair","traffic"],"explanation":"filled with despair 陷入绝望。"},{"q":"6","answer":"D","options":["waste","sell","hide","treasure"],"explanation":"treasure every small thing 珍视每件小事。"},{"q":"7","answer":"A","options":["die","drive","cook","shout"],"explanation":"learn how to die 学会面对死亡。"},{"q":"8","answer":"B","options":["sung","taken","driven","eaten"],"explanation":"be taken for granted 被视为理所当然。"},{"q":"9","answer":"C","options":["build","wash","miss","paint"],"explanation":"miss such beauty 错过这样的美。"},{"q":"10","answer":"D","options":["stopped","refused","failed","encouraged"],"explanation":"encouraged readers to slow down 鼓励读者慢下来。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U2', 'Keeping in Touch', 'After reading Tuesdays with Morrie, I thought about all the good (1)____ I had slowly lost touch with over the years. The book reminded me how (2)____ such people really are. One of its clearest lessons is that we should always keep in (3)____ with those who matter. Like Morrie, we want to reach the end of life (4)____ that we have loved and been loved. So last week I finally (5)____ an old classmate I had not seen for ages. At first I felt (6)____, but as soon as we started talking, the years seemed to (7)____ away. We laughed about the past and (8)____ to meet again soon. That evening I understood why the poet wrote, "Love each other or (9)____." A few warm words, I realised, can be more (10)____ than any expensive gift.', 137, 2, '[{"q":"1","answer":"A","options":["friends","prices","tickets","machines"],"explanation":"good friends 好友。"},{"q":"2","answer":"B","options":["cheap","precious","empty","loud"],"explanation":"how precious such people are 多么珍贵。"},{"q":"3","answer":"C","options":["line","price","touch","noise"],"explanation":"keep in touch 保持联系。"},{"q":"4","answer":"D","options":["selling","cooking","driving","knowing"],"explanation":"knowing that we have loved 知道自己爱过。"},{"q":"5","answer":"A","options":["contacted","cooked","painted","washed"],"explanation":"contacted an old classmate 联系了老同学。"},{"q":"6","answer":"B","options":["rich","nervous","late","tall"],"explanation":"felt nervous 感到紧张。"},{"q":"7","answer":"C","options":["build","wash","melt","paint"],"explanation":"the years seemed to melt away 岁月仿佛消融。"},{"q":"8","answer":"D","options":["refused","failed","forgot","promised"],"explanation":"promised to meet again 约定再见。"},{"q":"9","answer":"A","options":["perish","sing","cook","drive"],"explanation":"Love each other or perish 彼此相爱否则消亡。"},{"q":"10","answer":"B","options":["boring","important","cheap","empty"],"explanation":"more important than any gift 比礼物更重要。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U2', 'A Simple Life', 'In a world that often measures success by money, Morrie''s ideas feel refreshingly (1)____. He believed that happiness is not found in (2)____ such as fast cars or designer clothes. Real joy, he said, comes from simple (3)____: a good talk, a kind act, a quiet walk. Many people spend their whole lives (4)____ material possessions, only to feel empty in the end. Morrie warned that looking different from others does not make a person (5)____. What truly (6)____ is how we treat one another. He encouraged everyone to build their own (7)____ around love and honesty, instead of letting society (8)____ them. When I closed the book, I decided to (9)____ less about owning things and more about being kind. That single change has made my days far more (10)____.', 131, 2, '[{"q":"1","answer":"C","options":["heavy","noisy","simple","sharp"],"explanation":"refreshingly simple 清新而简单。"},{"q":"2","answer":"D","options":["mistakes","seasons","letters","luxuries"],"explanation":"found in luxuries 在于奢侈品。"},{"q":"3","answer":"A","options":["pleasures","prices","engines","tickets"],"explanation":"simple pleasures 简单的快乐。"},{"q":"4","answer":"B","options":["selling","chasing","washing","painting"],"explanation":"chasing material possessions 追逐物质财产。"},{"q":"5","answer":"C","options":["hungry","late","abnormal","tall"],"explanation":"make a person abnormal 让人变得反常。"},{"q":"6","answer":"D","options":["sells","drives","cooks","matters"],"explanation":"what truly matters 真正重要的。"},{"q":"7","answer":"A","options":["values","tickets","engines","prices"],"explanation":"build their own values 建立自己的价值观。"},{"q":"8","answer":"B","options":["sell","decide","wash","paint"],"explanation":"letting society decide them 让社会替你决定。"},{"q":"9","answer":"C","options":["drive","cook","care","sing"],"explanation":"care less about owning things 少在意拥有。"},{"q":"10","answer":"D","options":["boring","empty","noisy","meaningful"],"explanation":"far more meaningful 更有意义。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U2', 'The Book That Made Me Cry', 'A friend warned me that a box of tissues would be (1)____ to get through Tuesdays with Morrie, and she was right. The book is not (2)____, even though it is about a dying man. Morrie''s gentle (3)____ on love and friendship made me think about all the people I had lost (4)____ with over the years. I realised just how much I (5)____ them. One clear lesson of the book is that we should always keep in (6)____ with the good people we meet. Like Mitch, I now want to reach the end of my life (7)____ that I have loved and been loved. The story also (8)____ me to call an old friend that very night. We talked for hours, and a warm feeling slowly (9)____ my heart. Sometimes a single book can quietly (10)____ the way we live.', 141, 2, '[{"q":"1","answer":"A","options":["needed","sold","painted","washed"],"explanation":"a box of tissues would be needed 需要一盒纸巾。"},{"q":"2","answer":"B","options":["tall","sad","rich","loud"],"explanation":"the book is not sad 这本书并不悲伤。"},{"q":"3","answer":"C","options":["prices","engines","reflections","tickets"],"explanation":"Morrie''s reflections on love 莫里关于爱的沉思。"},{"q":"4","answer":"D","options":["price","noise","speed","contact"],"explanation":"lost contact with 失去联系。"},{"q":"5","answer":"A","options":["missed","sold","drove","cooked"],"explanation":"how much I missed them 多么想念他们。"},{"q":"6","answer":"B","options":["line","touch","price","noise"],"explanation":"keep in touch 保持联系。"},{"q":"7","answer":"C","options":["selling","cooking","knowing","driving"],"explanation":"knowing that I have loved 知道自己爱过。"},{"q":"8","answer":"D","options":["stopped","refused","failed","moved"],"explanation":"the story moved me to call 打动我去打电话。"},{"q":"9","answer":"A","options":["filled","sold","broke","washed"],"explanation":"a warm feeling filled my heart 暖意充满心间。"},{"q":"10","answer":"B","options":["wash","change","drive","paint"],"explanation":"change the way we live 改变我们的生活方式。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U2', 'Once You Learn How to Die', 'One of Morrie''s most famous (1)____ is this: "Once you learn how to die, you learn how to live." At first these words sound (2)____, but their meaning is deep. Morrie believed that when people accept that life is (3)____, they finally stop wasting their days. Too many of us, he said, are not really (4)____ to the world around us. We are easily (5)____ by small worries and forget what truly matters. By facing the end calmly, Morrie was able to (6)____ each ordinary day as a gift. He watched every (7)____ change from his window, knowing it might be his last. His quiet courage has been (8)____ as inspirational by readers everywhere. The book gently (9)____ us to wake up, open our eyes, and (10)____ the most of the time we have.', 134, 2, '[{"q":"1","answer":"C","options":["prices","engines","sayings","tickets"],"explanation":"famous sayings 名言。"},{"q":"2","answer":"D","options":["tall","rich","late","absurd"],"explanation":"sound absurd 听起来荒唐。"},{"q":"3","answer":"A","options":["short","cheap","loud","empty"],"explanation":"life is short 人生短暂。"},{"q":"4","answer":"B","options":["tall","awake","rich","cheap"],"explanation":"not really awake to the world 没真正清醒地面对世界。"},{"q":"5","answer":"C","options":["sold","painted","distracted","washed"],"explanation":"easily distracted by small worries 易被琐事分心。"},{"q":"6","answer":"D","options":["waste","sell","hide","treasure"],"explanation":"treasure each ordinary day 珍惜每个平凡的日子。"},{"q":"7","answer":"A","options":["season","price","noise","engine"],"explanation":"every season change 每次季节变化。"},{"q":"8","answer":"B","options":["eaten","described","driven","sung"],"explanation":"has been described as inspirational 被称为鼓舞人心。"},{"q":"9","answer":"C","options":["sells","drives","reminds","cooks"],"explanation":"the book reminds us 这本书提醒我们。"},{"q":"10","answer":"D","options":["wash","drive","sing","make"],"explanation":"make the most of the time 充分利用时间。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·对话 Talking About the Book', '外研社版选择性必修第四册 U2 · dialogue', 3, 'Lucy: Have you finished reading Tuesdays with Morrie yet?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·短文 About Morrie', '外研社版选择性必修第四册 U2 · passage', 2, 'Morrie Schwartz was once a much-loved college professor.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·对话 A Proverb About Life', '外研社版选择性必修第四册 U2 · dialogue', 3, 'Anna: Maths is really hard. I am thinking of giving it up.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·短文 Never Too Old to Learn', '外研社版选择性必修第四册 U2 · passage', 2, 'In most countries, students usually start university at about eighteen.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·对话 Old Friends Meet Again', '外研社版选择性必修第四册 U2 · dialogue', 3, 'Mia: Sam? Is that really you? I have not seen you for ten years!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U2 听力·短文 Make the Most of Today', '外研社版选择性必修第四册 U2 · passage', 2, 'Here is one simple lesson from Morrie''s story.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write a Book Review of Tuesdays with Morrie(写一篇《相约星期二》读后感/书评)', 'A Book That Changed the Way I Live', '假设你叫李华,学校英语社团征集“一本改变了我的书”的短文。请用英语写一篇约100词的书评,内容包括:① 简要介绍《相约星期二》(作者/人物/它讲什么);② 谈一条你从中学到的人生道理;③ 把它推荐给同学。注意:恰当使用被动语态(如 The book was written by…/We are reminded that…),语言准确连贯。', 'Suppose you are Li Hua. Your school English club is collecting short pieces titled ''A Book That Changed Me''. Write a book review (about 100 words) of Tuesdays with Morrie, including: 1) a brief introduction to the book (author, people, what it is about); 2) one life lesson you have learned from it; 3) a recommendation to your classmates. Use the passive voice naturally where appropriate.', '["简介这本书(written by Mitch Albom / it is about…)","你学到的一条道理(I was reminded that… / We should…)","推荐给同学(It should be read by everyone who…)","恰当、自然地使用被动语态,行文连贯"]'::jsonb, 70, 100, 'Tuesdays with Morrie was written by Mitch Albom, a busy journalist who was reunited with his old professor, Morrie. When it was discovered that Morrie was being weakened by a severe illness, Mitch began visiting him every Tuesday, and their talks were turned into this gentle book. I was deeply moved by one lesson: how we live should be chosen by ourselves, not decided by society. After reading it, I was reminded to value my family and to keep in touch with old friends. This book is filled with hope, and I believe it should be read by every young person at least once.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Tuesdays with Morrie was written by Mitch Albom, who was reunited with his old professor.","When it was discovered that Morrie was being weakened by a severe illness, Mitch began visiting him.","How we live should be chosen by ourselves, not decided by society.","This book is filled with hope, and it should be read by everyone at least once."]'::jsonb, '[{"wrong":"The book was wrote by Mitch Albom.","correct":"The book was written by Mitch Albom.","note":"被动语态用过去分词 written,不是过去式 wrote。"},{"wrong":"Morrie was weakened by a illness now.","correct":"Morrie is being weakened by an illness now.","note":"now 表示此刻正在进行 → 现在进行被动 is being done。"},{"wrong":"This book should read by everyone.","correct":"This book should be read by everyone.","note":"情态动词后的被动是 should be done,不能漏掉 be。"}]'::jsonb, '【《相约星期二》书评结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective4', 'U2', '{"title":"被动语态综合·各时态被动 + 非谓语被动 速查","intro":"被动语态 = be 的相应形式 + 过去分词(done)。主语是动作的承受者(被…)时用被动。判断口诀:先看主语是否‘被动作’,再由时间标志/句法环境决定 be 用什么形式。","table":{"headers":["时态/结构","被动形式 / 标志 / 例句"],"rows":[["一般现在","am/is/are done(today, usually):The book is loved by readers."],["一般过去","was/were done(ago, last…, in 1997):It was written in 1997."],["一般将来","will be done(tomorrow, next…):A film will be made next year."],["现在完成","has/have been done(already, so far, since):It has been translated."],["过去完成","had been done(by the time…, by 1997):It had been finished."],["现在进行","is/are being done(now, Look!):Morrie is being weakened."],["过去进行","was/were being done(while…, when… came):It was being recorded."],["情态被动","must/should/can + be done:Values must be chosen by yourself."],["不定式被动","to be done(need/want/ask + to be done):It needs to be passed on."],["动名词被动","being done(介词 despite/after/without/by 后):Despite being weakened…"]]},"specialRules":[{"rule":"主语是动作的发出者 → 仍用主动,别误用被动","mark":"Mitch visited Morrie.(Mitch 主动探望)"},{"rule":"主语是动作的承受者、常带 by… → 用被动","mark":"Morrie was visited by Mitch.(莫里被探望)"},{"rule":"情态/将来后的被动必须保留 be:must be done / will be done","mark":"should be read √ / should read ×(若主语被读)"},{"rule":"介词后用动名词被动 being done,不能用 to be done","mark":"Despite being weakened √ / Despite to be weakened ×"}],"why":["被动语态把‘动作的承受者’放到主语位置,强调被影响的人或物;当动作的发出者不重要、未知或泛指‘人们’时,常省略 by 短语。","无论哪种时态,变化的只是 be 这个部分;后面的过去分词 done 不变——抓住‘be 随时态变、done 不变’就不易错。"],"gaokaoPoints":["语法填空高频:给出动词原形,按时间标志/语境填正确的被动形式(is done / was done / has been done / is being done / had been done)。","非谓语:need/ask + to be done、介词 + being done、情态 + be done 的被动易漏 be 或 being。","主动 vs 被动:先判断主语是施动者还是受动者,再决定用不用被动(尤其 happen/rise/appear 等不及物动词无被动)。"],"examVsReal":[{"exam":"The window is being cleaned.(考试强调进行被动)","real":"Someone''s cleaning the window.","note":"口语里常用主动 + someone/they 来代替被动,显得更自然"},{"exam":"It is said that he is wise.(考试爱考 it is said/believed that…)","real":"People say he''s wise.","note":"考试偏好被动套语,日常更常用 people say…"}]}'::jsonb, 'fltrp');
